const fs = require('node:fs/promises');
const path = require('node:path');

const README_PATH = path.join(__dirname, 'README.md');
const OUTPUT_PATH = path.join(__dirname, 'results', 'status.json');

function findEndpoint(readme) {
  const match = readme.match(/https?:\/\/[^\s)]+\/status/);
  if (!match) {
    throw new Error('No /status endpoint found in README.md');
  }
  return match[0];
}

async function main() {
  const readme = await fs.readFile(README_PATH, 'utf8');
  const endpoint = findEndpoint(readme);

  const response = await fetch(endpoint);
  const payload = await response.json();

  if (!response.ok) {
    throw new Error(`Request to ${endpoint} failed with HTTP ${response.status}`);
  }
  if (payload.status !== 200) {
    throw new Error(`Expected status 200, received ${payload.status}`);
  }

  await fs.mkdir(path.dirname(OUTPUT_PATH), { recursive: true });
  await fs.writeFile(OUTPUT_PATH, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
  console.log(`Wrote ${OUTPUT_PATH} with status=${payload.status}`);
}

main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
```

